{
  "declined": "none",
  "items": [
    {
      "i": 0,
      "revised": "It rained all day today.",
      "why": "把原本的\"Today it rained all day.\" 調整為更自然的語序 \"It rained all day today.\"。",
      "zh": "今天下了一整天的雨。"
    },
    {
      "i": 1,
      "revised": "I didn't bring an umbrella, so my shoes got wet.",
      "why": "修正冠詞並以更自然的動詞\"got wet\"取代\"were wet\"。",
      "zh": "我沒有帶傘，所以我的鞋子淋濕了。"
    },
    {
      "i": 2,
      "revised": "My mom wasn't angry.",
      "why": "把否定縮短為更自然的縮寫\"wasn't\"。",
      "zh": "我媽媽沒有生氣。"
    },
    {
      "i": 3,
      "revised": "She made hot soup for me.",
      "why": "這句原本正確，保留但微調以符合自然語感。",
      "zh": "她為我煮了熱湯。"
    },
    {
      "i": 4,
      "revised": "Now I feel warm and happy.",
      "why": "把時間副詞放在句首前移，讓語序更自然為\"Now I feel warm and happy.\"。",
      "zh": "現在我覺得又溫暖又快樂。"
    }
  ]
}
